val refresher = scope.launch {
    while (isActive) {
        try {
            rate = fetchRate()
        } catch (e: CancellationException) {
            throw e                                  // let cancellation through
        } catch (e: Exception) {
            log.warn("FX refresh failed, keeping the last rate", e)
        }
        delay(5.seconds)                             // the gap is measured from the end of the run
    }
}

// later
refresher.cancel()         // stops at the next delay()

