ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
AtomicReference<Limits> limits = new AtomicReference<>();

ScheduledFuture<?> refresh = scheduler.scheduleWithFixedDelay(() -> {
    try {
        limits.set(loadLimits());                     // replace only on success
    } catch (RuntimeException e) {
        log.warn("limit refresh failed, keeping the old value", e);
    }
}, 0, 10, TimeUnit.SECONDS);

// to stop it
refresh.cancel(false);
scheduler.shutdown();

